// ============================================================================
// SCRIPT 1 - TỰ CLONE EMOJI / STICKER
// Ai đó gửi emoji server khác hoặc sticker -> bot kiểm tra server mình đã có chưa
// -> nếu CHƯA có thì tải về và thêm vào server (kèm báo kết quả).
//
// Cài trên web (tab Script):
//   Ngôn ngữ : JavaScript
//   Trigger  : <a?:\w{2,32}:\d{15,25}>|\[\[STICKER:\d+\]\]|^!clone\b
//   Kiểu khớp: regex
//   Cooldown : 2     Thời gian tối đa: 8000
//   (để trống ô "Chỉ nhận tin từ ID" và ô kênh = áp dụng mọi kênh)
//
// Lệnh bật/tắt (chỉ Admin / chủ server):  !clone on   |   !clone off   |   !clone (xem trạng thái)
// Bot cần quyền "Manage Guild Expressions" (Quản lý emoji & sticker).
// ============================================================================

// ------------------------------ CẤU HÌNH ------------------------------------
const MAX_EMOJI = 5;      // tối đa số emoji clone từ 1 tin nhắn
const CLONE_STICKER = true; // true = clone cả sticker
const VERBOSE = false;    // true = báo cả khi server đã có sẵn (mặc định im lặng cho đỡ spam)
// ----------------------------------------------------------------------------

const text = String(ctx.content || '');
const isStaff = ctx.user.isAdmin || ctx.user.isOwner;

// ---- Lệnh bật / tắt ----
const cmd = text.trim().match(/^!clone(?:\s+(\S+))?/i);
if (cmd) {
  const arg = (cmd[1] || '').toLowerCase();
  if (['on', 'bat', 'bật'].includes(arg) || ['off', 'tat', 'tắt'].includes(arg)) {
    if (!isStaff) return 'Chỉ Admin / chủ server mới bật tắt được.';
    store.enabled = ['on', 'bat', 'bật'].includes(arg);
    return store.enabled ? '✅ Đã **BẬT** tự clone emoji/sticker.' : '⛔ Đã **TẮT** tự clone emoji/sticker.';
  }
  return 'Clone emoji/sticker đang **' + (store.enabled === false ? 'TẮT' : 'BẬT') + '**. Dùng `!clone on` / `!clone off`.';
}
if (store.enabled === false) return;
if (!ctx.guildId) return;

const L = ctx.limits || {};
const haveEmojiId = new Set((ctx.guildEmojis || []).map(e => e.id));
const haveEmojiName = new Set((ctx.guildEmojis || []).map(e => e.name.toLowerCase()));
const haveStickerId = new Set((ctx.guildStickers || []).map(s => s.id));
const haveStickerName = new Set((ctx.guildStickers || []).map(s => s.name.toLowerCase()));
const uniqueName = (name, taken) => {
  let n = name, i = 2;
  while (taken.has(n.toLowerCase())) n = name.slice(0, 29) + '_' + i++;
  taken.add(n.toLowerCase());
  return n;
};

let usedStatic = L.emojiStatic || 0, usedAnim = L.emojiAnimated || 0, usedSticker = L.stickerUsed || 0;
let queued = 0;
const skipped = [];

// ---- 1) EMOJI ----
const seen = new Set();
for (const m of text.matchAll(/<(a?):(\w{2,32}):(\d{15,25})>/g)) {
  const [, anim, name, id] = m;
  if (seen.has(id)) continue; seen.add(id);
  if (haveEmojiId.has(id)) { skipped.push('emoji `' + name + '` đã có'); continue; }
  if (queued >= MAX_EMOJI) { skipped.push('emoji `' + name + '` (vượt giới hạn ' + MAX_EMOJI + ' emoji/tin)'); continue; }
  const animated = !!anim;
  if (L.emojiMax && (animated ? usedAnim : usedStatic) >= L.emojiMax) {
    skipped.push('emoji `' + name + '` (server hết slot emoji ' + (animated ? 'động' : 'tĩnh') + ' ' + L.emojiMax + '/' + L.emojiMax + ')');
    continue;
  }
  const url = 'https://cdn.discordapp.com/emojis/' + id + '.' + (animated ? 'gif' : 'png') + '?size=128';
  addEmoji(url, uniqueName(name, haveEmojiName), { animated, srcId: id });
  animated ? usedAnim++ : usedStatic++;
  queued++;
}

// ---- 2) STICKER ----
if (CLONE_STICKER) {
  for (const s of (ctx.stickers || []).slice(0, 1)) {
    if (haveStickerId.has(s.id)) { skipped.push('sticker `' + s.name + '` đã có'); continue; }
    if (s.format === 3) { skipped.push('sticker `' + s.name + '` (dạng Lottie, bot không thể upload)'); continue; }
    if (L.stickerMax && usedSticker >= L.stickerMax) { skipped.push('sticker `' + s.name + '` (server hết slot sticker ' + L.stickerMax + '/' + L.stickerMax + ')'); continue; }
    const url = s.format === 4
      ? 'https://media.discordapp.net/stickers/' + s.id + '.gif'
      : 'https://cdn.discordapp.com/stickers/' + s.id + '.png';
    addSticker(url, uniqueName(s.name, haveStickerName), { stickerId: s.id });
    usedSticker++; queued++;
  }
}

// Chỉ báo những lý do đáng chú ý (hết slot, Lottie, vượt giới hạn). "Đã có" chỉ báo khi VERBOSE.
const notable = skipped.filter(x => !x.endsWith('đã có'));
const toShow = VERBOSE ? skipped : notable;
if (toShow.length) return '⚠️ Không clone được: ' + toShow.join('; ');
if (queued) print('Đang clone ' + queued + ' mục');

// ============================================================================
// SCRIPT 2 - AI OLLAMA (chạy local) TRẢ LỜI KHI BỊ TAG HOẶC BỊ REPLY
// Trả lời cực ngắn (1-2 từ), cục súc, chửi bậy. Có công tắc bật/tắt.
//
// Cài trên web (tab Script):
//   Ngôn ngữ : JavaScript
//   Trigger  : \[\[BOT_TAGGED\]\]|^!ai\b
//   Kiểu khớp: regex
//   Kiểu trả : reply      Cooldown: 3      Thời gian tối đa: 15000
//   (ô "Chỉ nhận tin từ ID" để TRỐNG)
//
// Yêu cầu: máy chạy bot đã cài Ollama và đã pull model:
//     ollama pull qwen2.5:7b        (nói tiếng Việt tốt hơn llama3.2)
//
// Lệnh (bật/tắt/đổi model chỉ Admin / chủ server):
//   !ai on | !ai off          bật / tắt AI
//   !ai model <tên model>     đổi model
//   !ai clear                 xóa trí nhớ cuộc trò chuyện
//   !ai                       xem trạng thái
// ============================================================================

// ------------------------------ CẤU HÌNH ------------------------------------
const OLLAMA_URL = 'http://127.0.0.1:11434/api/chat';
const DEFAULT_MODEL = 'qwen2.5:7b';
const MAX_WORDS = 2;        // số từ tối đa của câu trả lời (1-2 từ)
const MEMORY_TURNS = 6;     // nhớ bao nhiêu tin gần nhất của mỗi kênh
const HTTP_TIMEOUT = 13000; // ms (phải nhỏ hơn "Thời gian tối đa" của script)

const SYSTEM_PROMPT = [
  'Mày là một thằng bạn cục súc, mất dạy, nói chuyện kiểu chợ búa trên mạng.',
  'LUÔN trả lời bằng tiếng Việt, đúng 1 đến 2 TỪ, tuyệt đối không giải thích, không dài dòng, không xin lỗi, không chào hỏi.',
  'Giọng điệu thô tục, chửi thề, gắt gỏng, xéo xắt, ví dụ: "đm", "câm mồm", "ngu vl", "cút", "khùng à", "cc", "biến", "vãi lồn".',
  'Chỉ chửi kiểu cợt nhả, trêu chọc giữa bạn bè. KHÔNG xúc phạm chủng tộc, tôn giáo, giới tính, khuyết tật hay dòng tộc người khác; KHÔNG đe dọa bạo lực thật.',
  'Nếu câu hỏi đòi thông tin thật, vẫn trả lời cộc lốc 1-2 từ.',
  'Chỉ in ra câu trả lời, không giải thích, không ngoặc kép, không emoji.'
].join('\n');
// ----------------------------------------------------------------------------

const isStaff = ctx.user.isAdmin || ctx.user.isOwner;
const text = String(ctx.content || '').trim();
const model = store.model || DEFAULT_MODEL;

// ---- Lệnh điều khiển ----
const cmd = text.match(/^!ai(?:\s+(\S+))?(?:\s+(.+))?$/i);
if (cmd) {
  const sub = (cmd[1] || '').toLowerCase(), arg = (cmd[2] || '').trim();
  const needStaff = () => { if (!isStaff) { reply('Chỉ Admin / chủ server mới dùng được.'); return true; } return false; };
  if (['on', 'bat', 'bật'].includes(sub)) {
    if (needStaff()) return;
    store.enabled = true; return '✅ AI đã **BẬT**. Tag hoặc reply bot để nói chuyện.';
  }
  if (['off', 'tat', 'tắt'].includes(sub)) {
    if (needStaff()) return;
    store.enabled = false; return '⛔ AI đã **TẮT**.';
  }
  if (sub === 'model') {
    if (needStaff()) return;
    if (!arg) return 'Model hiện tại: `' + model + '`';
    store.model = arg; return 'Đã đổi model sang `' + arg + '`';
  }
  if (sub === 'clear') {
    if (needStaff()) return;
    store.hist = {}; return '🧹 Đã xóa trí nhớ.';
  }
  return 'AI đang **' + (store.enabled === false ? 'TẮT' : 'BẬT') + '** | model: `' + model + '`';
}

// ---- Chỉ trả lời khi đang bật ----
if (store.enabled === false) return;

// ---- Chuẩn bị nội dung người dùng ----
let q = text
  .replace(/\[\[BOT_TAGGED\]\]/g, '')
  .replace(/<@!?\d{15,25}>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
if (!q) q = '(chỉ gọi tên, không nói gì)';
const refText = ctx.reply && ctx.reply.content ? String(ctx.reply.content).slice(0, 300) : '';
const userLine = (refText ? '[đang trả lời tin: "' + refText + '"] ' : '') + ctx.user.display + ': ' + q.slice(0, 400);

store.hist = store.hist || {};
const hist = store.hist[ctx.channelId] = store.hist[ctx.channelId] || [];

const messages = [{ role: 'system', content: SYSTEM_PROMPT }, ...hist, { role: 'user', content: userLine }];

// ---- Gọi Ollama ----
const ac = new AbortController();
const timer = setTimeout(() => ac.abort(), HTTP_TIMEOUT);
let out = '';
try {
  const res = await fetch(OLLAMA_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    signal: ac.signal,
    body: JSON.stringify({
      model, messages, stream: false, keep_alive: '30m',
      options: { temperature: 0.9, top_p: 0.9, num_predict: 24 }
    })
  });
  if (!res.ok) throw new Error('Ollama trả về HTTP ' + res.status + ' - ' + (await res.text()).slice(0, 200));
  const data = await res.json();
  out = String((data.message && data.message.content) || '');
} catch (e) {
  throw new Error(e.name === 'AbortError'
    ? 'Ollama quá chậm (>' + HTTP_TIMEOUT + 'ms) - model đang nạp? thử lại / dùng model nhỏ hơn'
    : 'Không gọi được Ollama (' + OLLAMA_URL + '): ' + e.message + ' - đã chạy "ollama serve" và "ollama pull ' + model + '" chưa?');
} finally { clearTimeout(timer); }

// ---- Làm sạch + ép ngắn 1-2 từ ----
out = out
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .split('\n').map(s => s.trim()).filter(Boolean)[0] || '';
out = out.replace(/^["'“”‘’`*_\-–\s]+|["'“”‘’`*_\s]+$/g, '').replace(/^(mày|bot|ai)\s*[:：]\s*/i, '');
const words = out.split(/\s+/).filter(Boolean).slice(0, MAX_WORDS);
out = words.join(' ').replace(/[.,;:!?…]+$/, '');
if (!out) out = 'cút';

// ---- Lưu trí nhớ ----
hist.push({ role: 'user', content: userLine }, { role: 'assistant', content: out });
while (hist.length > MEMORY_TURNS * 2) hist.shift();

return out;

// SCRIPT 1 - NẠP TỪ ĐIỂN: gửi link GitHub chứa các file Viet*.txt (Viet11K.txt, Viet22K.txt...) cho bot.
// Bot tải về, gộp, nén và lưu vào data.json (shared.vtv_dict). Script 2 dùng dữ liệu này để đoán từ.
// Link hỗ trợ: github.com/user/repo | .../tree/nhánh/thư-mục | .../blob/nhánh/file.txt | raw.githubusercontent.com/...
const zlib = require('zlib');
const ALLOWED_IDS = [];   // ID được phép nạp. Để trống = chỉ Admin / chủ server.
if (!(ctx.user.isAdmin || ctx.user.isOwner || ALLOWED_IDS.includes(ctx.user.id))) return;

const NAME_RE = /(^|\/)viet[^\/]*\.txt$/i;
const KNOWN = ['Viet11K.txt', 'Viet22K.txt', 'Viet39K.txt', 'Viet74K.txt'];
const UA = { 'User-Agent': 'discord-bot-nap-tu-dien' };
const enc = p => p.split('/').map(encodeURIComponent).join('/');
const rawUrl = (o, r, ref, p) => 'https://raw.githubusercontent.com/' + o + '/' + r + '/' + encodeURIComponent(ref) + '/' + enc(p);
async function getJson(u) {
  const r = await fetch(u, { headers: { ...UA, Accept: 'application/vnd.github+json' } });
  if (!r.ok) throw new Error('GitHub trả về ' + r.status + ' cho ' + u);
  return r.json();
}
async function exists(u) { try { return (await fetch(u, { method: 'HEAD', headers: UA })).ok; } catch { return false; } }
async function getText(u) {
  const r = await fetch(u, { headers: UA });
  if (!r.ok) throw new Error('Tải lỗi ' + r.status + ': ' + u);
  const t = await r.text();
  if (t.length > 6000000) throw new Error('File quá lớn: ' + u);
  return t.replace(/^\ufeff/, '');
}

try {
  const urls = (ctx.content.match(/https?:\/\/[^\s<>)\]]+/g) || []).map(u => u.replace(/[.,;]+$/, ''));
  const files = [];
  for (const url of urls) {
    let U; try { U = new URL(url); } catch { continue; }
    const host = U.hostname.toLowerCase().replace(/^www\./, '');
    const parts = U.pathname.split('/').filter(Boolean).map(decodeURIComponent);
    if (host === 'raw.githubusercontent.com') {
      if (/\.txt$/i.test(U.pathname)) files.push({ name: parts[parts.length - 1], url });
    } else if (host === 'github.com') {
      const [o, r0, kind, ref, ...rest] = parts;
      if (!o || !r0) continue;
      const repo = r0.replace(/\.git$/i, '');
      if ((kind === 'blob' || kind === 'raw') && ref && rest.length) {
        files.push({ name: rest[rest.length - 1], url: rawUrl(o, repo, ref, rest.join('/')) });
        continue;
      }
      const prefix = kind === 'tree' ? rest.join('/') : '';
      try {
        const branch = kind === 'tree' && ref ? ref : (await getJson('https://api.github.com/repos/' + o + '/' + repo)).default_branch;
        const tree = await getJson('https://api.github.com/repos/' + o + '/' + repo + '/git/trees/' + encodeURIComponent(branch) + '?recursive=1');
        for (const t of tree.tree || []) {
          if (t.type === 'blob' && NAME_RE.test(t.path) && (!prefix || t.path.startsWith(prefix + '/')))
            files.push({ name: t.path.split('/').pop(), url: rawUrl(o, repo, branch, t.path) });
        }
      } catch (e) {
        // API GitHub bị giới hạn lượt gọi / lỗi -> thử tải thẳng các tên file quen thuộc ở nhánh main, master
        print('GitHub API lỗi (' + e.message + ') -> thử tải thẳng ' + KNOWN.join(', '));
        for (const br of [kind === 'tree' && ref ? ref : null, 'main', 'master'].filter(Boolean)) {
          const hits = [];
          for (const nm of KNOWN) {
            const u = rawUrl(o, repo, br, (prefix ? prefix + '/' : '') + nm);
            if (await exists(u)) hits.push({ name: nm, url: u });
          }
          if (hits.length) { files.push(...hits); break; }
        }
      }
    }
  }
  const uniq = [...new Map(files.map(f => [f.url, f])).values()].slice(0, 8);
  if (!uniq.length) { reply('❌ Không thấy file Viet*.txt nào trong link này.'); return; }

  // Cách đọc từ giống doan_tu.py: NFC, thường, bỏ dòng trống / có số, gộp dấu cách + gạch nối
  const parse = text => {
    const set = new Set();
    for (const line of text.split(/\r?\n/)) {
      const w = line.normalize('NFC').trim().toLowerCase();
      if (!w || /\d/.test(w)) continue;
      set.add(w.replace(/[\s\-]+/g, ' '));
    }
    return [...set];
  };
  const loaded = await Promise.all(uniq.map(async f => ({ name: f.name, words: parse(await getText(f.url)) })));
  loaded.sort((a, b) => a.words.length - b.words.length);   // file nhỏ = từ thông dụng hơn -> ưu tiên khi đoán

  const seen = new Set(), all = [], bounds = [], info = [];
  for (const f of loaded) {
    let added = 0;
    for (const w of f.words) if (!seen.has(w)) { seen.add(w); all.push(w); added++; }
    bounds.push(all.length);
    info.push({ name: f.name, words: f.words.length, added });
  }
  const C = zlib.constants;
  const br = zlib.brotliCompressSync(Buffer.from(all.join('\n'), 'utf8'), { params: { [C.BROTLI_PARAM_QUALITY]: 11 } }).toString('base64');
  if (br.length > 450000) { reply('❌ Dữ liệu sau nén quá lớn (' + Math.round(br.length / 1024) + ' KB), vượt giới hạn output của bot (512 KB).'); return; }

  shared.vtv_dict = { v: 1, src: urls.join(' '), at: ctx.now, total: all.length, bounds, files: info, br };
  print('Đã nạp ' + all.length + ' từ, nén ' + Math.round(br.length / 1024) + ' KB');
  reply('✅ Đã nạp **' + all.length.toLocaleString('en-US') + '** từ vào data.json (~' + Math.round(br.length / 1024) + ' KB nén).\n' +
    info.map(f => '• ' + f.name + ': ' + f.words + ' từ (mới ' + f.added + ')').join('\n'));
} catch (e) {
  reply('❌ Nạp từ điển lỗi: ' + (e && e.message ? e.message : e));
}

// SCRIPT 2 - VUA TIẾNG VIỆT (tự đoán): đọc tin của bot game, giải từ xáo chữ theo logic doan_tu.py rồi gửi đáp án vào kênh.
// Chỉ nhận tin từ ID đã khai ở ô "Chỉ nhận tin từ ID" (cho phép cả bot). Cần nạp từ điển bằng Script 1 trước.
// Mẫu tin: "Từ cần đoán: c/ò/n/l/n/h/h/ạ/g (gồm 9 ký tự)."
const zlib = require('zlib');
const MAX_SEND = 1;   // số đáp án gửi (xếp theo độ thông dụng). Nếu có nhiều từ cùng khớp, tăng lên 2-3 để thử thêm.

const lines = String(ctx.content || '').normalize('NFC').split('\n');
const li = lines.findIndex(l => /từ\s*cần\s*đoán/i.test(l));
if (li < 0) return;
const isL = c => /\p{L}/u.test(c);
const take = l => l.replace(/^.*?từ\s*cần\s*đoán\s*[*_\x60~]*\s*[:：]?/i, '').split(/\(\s*gồm/i)[0];
let chars = [...take(lines[li]).toLowerCase()].filter(isL);
if (!chars.length && lines[li + 1]) chars = [...lines[li + 1].split(/\(\s*gồm/i)[0].toLowerCase()].filter(isL);
const declared = +((lines[li].match(/gồm\s*(\d+)/i) || [])[1] || 0);
if (!chars.length) { print('Không đọc được ký tự từ tin nhắn.'); return; }
if (declared && declared !== chars.length) print('Cảnh báo: đề ghi ' + declared + ' ký tự nhưng đọc được ' + chars.length);

const D = shared.vtv_dict;
if (!D || !D.br) { print('Chưa có từ điển. Admin hãy gửi link git chứa Viet*.txt cho bot (Script 1).'); return; }
const words = zlib.brotliDecompressSync(Buffer.from(D.br, 'base64')).toString('utf8').split('\n');
const tierOf = i => { let t = 0; while (t < D.bounds.length - 1 && i >= D.bounds[t]) t++; return t; };

const lettersOf = w => [...w].filter(isL);
const strip = s => s.replace(/đ/g, 'd').replace(/Đ/g, 'D').normalize('NFD').replace(/\p{Mn}/gu, '').normalize('NFC');
const n = chars.length;
const key = chars.slice().sort().join('');
const lkey = [...strip(chars.join(''))].sort().join('');

// 1) khớp đúng dấu  2) khớp bỏ dấu  3) gợi ý thiếu 1 ký tự (chỉ ghi log, không gửi)
const exact = [], loose = [], near = [];
const have = {}; for (const c of chars) have[c] = (have[c] || 0) + 1;
words.forEach((w, i) => {
  const ls = lettersOf(w);
  if (ls.length === n) {
    if (ls.slice().sort().join('') === key) exact.push([tierOf(i), w]);
    else if ([...strip(ls.join(''))].sort().join('') === lkey) loose.push([tierOf(i), w]);
  } else if (ls.length === n - 1) {
    const cnt = {}; for (const c of ls) cnt[c] = (cnt[c] || 0) + 1;
    if (Object.keys(cnt).every(c => (have[c] || 0) >= cnt[c])) near.push([tierOf(i), w]);
  }
});
const rank = a => a.sort((x, y) => x[0] - y[0] || (x[1] < y[1] ? -1 : x[1] > y[1] ? 1 : 0)).map(x => x[1]);

let mode = 'khớp đúng dấu', res = rank(exact);
if (!res.length) { mode = 'khớp khi bỏ dấu'; res = rank(loose); }
if (!res.length) {
  print('Ký tự (' + n + '): ' + chars.join('/') + ' -> không có từ khớp đủ. Gợi ý thiếu 1 ký tự: ' + rank(near).slice(0, 10).join(' | '));
  return;
}
print('Ký tự (' + n + '): ' + chars.join('/') + ' -> ' + mode + ' ' + res.length + ' từ: ' + res.slice(0, 10).join(' | '));
res.slice(0, MAX_SEND).forEach(w => reply(w));

// !tx tai 100  |  !tx xiu 100  |  !tx (xem số xu)
const bal = shared.coins = shared.coins || {};
const uid = ctx.user.id;
if (bal[uid] === undefined) bal[uid] = 1000;
const side = (ctx.args[0] || '').toLowerCase();
const bet = parseInt(ctx.args[1], 10);
if (!['tai', 'xiu', 'tài', 'xỉu'].includes(side) || !(bet > 0)) {
  reply(ctx.user.mention + ' bạn có **' + bal[uid] + '** xu.\nCách chơi: !tx tai 100 hoặc !tx xiu 100');
  return;
}
if (bet > bal[uid]) { reply(ctx.user.mention + ' không đủ xu (còn ' + bal[uid] + ').'); return; }
const d = [1, 2, 3].map(() => 1 + Math.floor(Math.random() * 6));
const sum = d[0] + d[1] + d[2];
const triple = d[0] === d[1] && d[1] === d[2];
const result = sum >= 11 ? 'tài' : 'xỉu';
const pick = side.startsWith('t') ? 'tài' : 'xỉu';
const win = !triple && pick === result;
bal[uid] += win ? bet : -bet;
reply('🎲 ' + d.join(' + ') + ' = **' + sum + '** → **' + (triple ? 'bão (nhà cái ăn)' : result) + '**\n' +
  ctx.user.mention + (win ? ' thắng +' : ' thua -') + bet + ' xu. Số dư: **' + bal[uid] + '**');

// !nt con mèo  ->  người sau gõ !nt mèo ăn ...
const word = ctx.rest.trim().toLowerCase().replace(/\s+/g, ' ');
const syl = w => w.split(' ');
store.used = store.used || [];
if (!word) {
  reply(store.last ? 'Từ hiện tại: **' + store.last + '** → hãy nối bằng từ bắt đầu bằng **' + syl(store.last).at(-1) + '**' : 'Gõ !nt <từ gồm 2 tiếng> để bắt đầu.');
  return;
}
if (syl(word).length !== 2) { reply('Từ phải gồm đúng 2 tiếng, vd: con mèo'); return; }
if (store.used.includes(word)) { reply('Từ **' + word + '** đã dùng rồi!'); return; }
if (store.last && syl(word)[0] !== syl(store.last).at(-1)) {
  reply('Sai rồi! Từ phải bắt đầu bằng **' + syl(store.last).at(-1) + '**'); return;
}
store.last = word; store.used.push(word);
if (store.used.length > 500) store.used.shift();
reply('✅ **' + word + '** → tiếp theo: từ bắt đầu bằng **' + syl(word)[1] + '**');
